import {defaults,evaluate} from './bed-model.mjs';
import {summarizePlan} from './bed-planning.mjs';
const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(v,d=3)=>v===Infinity?'∞':typeof v==='number'&&Number.isFinite(v)?v.toLocaleString('zh-CN',{maximumFractionDigits:d}):'待补参数';
const capacityNum=v=>v===Infinity?'入口已满足 / 不构成限制':num(v);
const labels={S:'S / wt%',C:'C / wt%',Odiss:'溶解氧 / ppm',TO:'总氧 / ppm',H:'H / ppm',N:'N / ppm',P:'P / wt%',Cu:'Cu / wt%',Sn:'Sn / wt%',T:'钢温 / °C',Si:'Si / wt%',Mn:'Mn / wt%',Al:'Al / wt%',Cr:'Cr / wt%',Ni:'Ni / wt%',Mo:'Mo / wt%'};
let uiView='design',selectedModuleId=null,systemAudit=null;const openDisclosures=new Set();
let catalogue=[],types={};const legacy={PRE:'SKIM',DESULF:'LF',DEOX:'LF',DECARB:'RHOB',TUNDISH:'TD',GAS:'AR',HEAT:'TDHEAT'};const typeName=t=>t==='TRANSFER'?'未分配连续输送段':types[t]||t;
let state;try{const saved=JSON.parse(localStorage.getItem('continuous-bed-v1'));if(saved?.modules){Object.assign(saved,migrateParallel(saved));}if(saved&&evaluate(saved).valid)state=saved;}catch{}state ||= defaults();let evidence=null,status='设计示例已载入；未知反应与传热参数保持空白。';
function limits(path){const key=path.split('.').at(-1);if(key==='lengthM')return path.startsWith('modules.')?[.5,3,.5]:[1,50,.5];if(key==='flowTph')return [.1,100,.1];if(key==='radiusM')return [.05,2,.01];if(key==='depthM')return [.01,2,.01];if(key==='densityKgM3')return [5000,8000,10];if(key==='cpKJkgK')return [.4,1.2,.01];if(['T','targetOutletC','liquidusC','measuredInletC','measuredOutletC'].includes(key))return [1300,1800,1];if(['heatEfficiency','coveredFraction','reactedFraction'].includes(key))return [0,1,.01];if(key==='kPerMin')return [0,2,.001];if(['gasNLmin','topGasNLmin','bottomGasNLmin'].includes(key))return [0,2000,10];if(key==='powderKgMin')return [0,100,.5];if(key==='heatKW')return [0,5000,10];if(key==='reactionMJkg')return [0,50,.1];if(key==='oxygenKgPerKg')return [0,4,.01];if(['alloyKgT','availableOxygenKgT','heatAvailableOxygenKgT','totalAvailableOxygenKgT','slagRemovalKgT'].includes(key))return [0,100,.1];if(key.endsWith('FluxKWm2'))return [0,500,1];if(['Odiss','TO'].includes(key))return [0,500,1];if(key==='H')return [0,20,.1];if(key==='N')return [0,1000,1];if(['target','equilibrium'].includes(key)){const index=+path.split('.')[1],sp=state.modules[index]?.species;return ['TO','Odiss','N'].includes(sp)?[0,500,1]:sp==='H'?[0,20,.1]:[0,2,.001];}return ['S','P','Sn','Al'].includes(key)?[0,.1,.001]:[0,20,.01];}
function field(path,label,value,extra=''){const [low,high,step]=limits(path),min=Math.min(low,value??low),max=Math.max(high,value??high);return `<label class="range-field">${label}<output data-output="${path}">${num(value,6)}</output><input aria-label="${esc(label)}" type="range" min="${min}" max="${max}" step="${step}" data-path="${path}" value="${value??min}" ${extra}><small>${value==null?'拖动后指定；当前未知':'拖动滑条调整'}</small>${value==null||path.startsWith('geometry.')||path.startsWith('inlet.')||path.startsWith('targets.')||path==='flowTph'||path==='thermal.coveredFraction'||/^modules\.\d+\.lengthM$/.test(path)?'':`<button class="clear-value" type="button" data-clear="${path}">设为未知</button>`}</label>`;}
const options=(list,value)=>Object.entries(list).map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('');
function selector(path,label,list,value){return `<label>${label}<select data-path="${path}" data-text>${options(list,value)}</select></label>`}
function save(){localStorage.setItem('continuous-bed-v1',JSON.stringify(state))}
function migrateParallel(config){const c=structuredClone(config),old=(c.modules||[]).map(m=>({...m,type:legacy[m.type]||m.type,lengthM:Math.max(.5,Math.min(3,Math.round(m.lengthM*2)/2))})),overlay=['SKIM','AR','POWDER','TDHEAT'];const hosts=old.filter(m=>!overlay.includes(m.type));let notes=[];if(!hosts.length&&old.length){hosts.push({...old[0],id:crypto.randomUUID(),type:'TRANSFER',species:'',lengthM:old[0].lengthM,kPerMin:null,equilibrium:null,heatKW:null,heatingMethod:'none',gas:'none',gasNLmin:0});notes.push('旧方案只有辅助操作，已用连续输送段承载并行操作，不新增精炼设备。');}for(const h of hosts){h.heatingEnabled??=!!(h.heatingMethod&&h.heatingMethod!=='none'||h.heatKW>0);h.skimmingEnabled??=false;if(h.heatingMethod==='powder'&&h.species!=='C'&&h.heatAvailableOxygenKgT==null)h.heatAvailableOxygenKgT=h.availableOxygenKgT??null;if(h.blowingMode===undefined){h.blowingMode=h.gas&&h.gas!=='none'?'bottom':'none';h.bottomGas=h.gas||'Ar';h.bottomGasNLmin=h.gasNLmin??null;h.topGas='Ar';h.topGasNLmin=null;}}for(const op of old.filter(m=>overlay.includes(m.type))){const ix=old.indexOf(op),prev=old.slice(0,ix).reverse().find(m=>hosts.some(h=>h.id===m.id)),h=prev?hosts.find(h=>h.id===prev.id):hosts[0];if(!h)continue;let applied=false;if(op.type==='TDHEAT'&&!h.heatingEnabled){for(const key of ['heatKW','heatEfficiency','heatingMethod','reactionMJkg','reactedFraction','oxygenKgPerKg'])h[key]=op[key];h.heatAvailableOxygenKgT=op.heatAvailableOxygenKgT??op.availableOxygenKgT??null;if(op.totalAvailableOxygenKgT!=null)h.totalAvailableOxygenKgT=op.totalAvailableOxygenKgT;h.heatingEnabled=true;h.heatingMethod=op.heatingMethod||'induction';applied=true;}if(op.type==='SKIM'&&!h.skimmingEnabled){h.skimmingEnabled=true;h.slagRemovalKgT=op.slagRemovalKgT??null;applied=true;}if(['AR','POWDER'].includes(op.type)&&h.blowingMode==='none'){h.blowingMode=op.type==='POWDER'?'top':'bottom';const side=h.blowingMode;h[side+'Gas']=op.gas==='none'?'Ar':op.gas||'Ar';h[side+'GasNLmin']=op.gasNLmin??null;if(op.type==='POWDER'){h.powderKgMin=op.powderKgMin??null;h.powderInjection='top';}applied=true;}c.parallelMigrationArchive??=[];c.parallelMigrationArchive.push({operation:op,hostId:h.id,applied});notes.push(`${op.type}原独立床段已取消，${applied?'附着到相邻区段':'与相邻操作冲突，原设置保存在方案归档，需手动选择'}；原占用长度回到未分配床长；原辅助段动力学未自动转移，仍在归档中。`);}c.modules=hosts;if(notes.length)c.parallelMigrationNotes=[...(c.parallelMigrationNotes||[]),...notes];return c;}
function freshModule(type){const suggested={LF:'S',RH:'C',RHOB:'C',VD:'H',VAD:'H',SOFT:'TO',TD:''},item=catalogue.find(x=>x.equipment_id===type);return{id:crypto.randomUUID(),type,lengthM:1,flowModel:'PFR',species:suggested[type]??'',kPerMin:null,equilibrium:null,target:null,blowingMode:'none',topGas:'Ar',topGasNLmin:null,bottomGas:'Ar',bottomGasNLmin:null,powderInjection:'top',powderKgMin:0,alloyKgT:0,skimmingEnabled:false,slagRemovalKgT:null,heatingEnabled:false,heatKW:null,heatEfficiency:null,heatingMethod:'induction',evidenceIds:item?.source_ids||[]};}
const gasOptions={Ar:'氩气 Ar',N2:'氮气 N₂',O2:'氧气 O₂'};
function boolSelect(path,label,value){return `<label>${label}<select data-path="${path}" data-bool>${options({false:'否',true:'是'},String(!!value))}</select></label>`;}
function upperControls(m,i){const top=['top','combined'].includes(m.blowingMode),bottom=['bottom','combined'].includes(m.blowingMode);return `<div class="parallel-top"><strong>第${i+1}区 · 上方并行操作</strong><div class="parallel-selects">${boolSelect(`modules.${i}.skimmingEnabled`,'是否扒渣',m.skimmingEnabled)}${selector(`modules.${i}.blowingMode`,'喷吹方法',{none:'无喷吹',top:'顶吹',bottom:'底吹',combined:'顶底复吹'},m.blowingMode||'none')}${top?selector(`modules.${i}.topGas`,'顶吹气体',gasOptions,m.topGas||'Ar'):''}${bottom?selector(`modules.${i}.bottomGas`,'底吹气体',gasOptions,m.bottomGas||'Ar'):''}</div><small class="parallel-hint">${m.skimmingEnabled?'扒渣已启用 · ':''}${m.blowingMode==='none'?'无喷吹':`${top?'顶吹 '+(m.topGas||'Ar'):''}${top&&bottom?' + ':''}${bottom?'底吹 '+(m.bottomGas||'Ar'):''}`}<br>与本段精炼同时进行，不另加床长或通过时间</small></div>`;}
function lowerControls(m,i){return `<div class="parallel-bottom"><strong>第${i+1}区 · 下方并行补热</strong><div class="parallel-selects">${boolSelect(`modules.${i}.heatingEnabled`,'是否需要补热',m.heatingEnabled)}${m.heatingEnabled?selector(`modules.${i}.heatingMethod`,'补热手段',{induction:'电磁 / 感应',plasma:'等离子',powder:'喷粉化学补热',other:'其他'},m.heatingMethod||'induction'):''}</div><small data-heat-indicator="${i}">${m.heatingEnabled?(m.heatingMethod==='powder'?'喷粉补热':'输入 '+num(m.heatKW)+' kW'):'未启用补热 · 输入计0'}</small></div>`;}
function equipmentNote(m){const x=catalogue.find(x=>x.equipment_id===m.type);return x?`<div class="catalogue-note"><strong>数据包设备 ${esc(x.equipment_id)} · ${esc(x.name)}</strong><br>作用：${esc(x.functions)}<br>原设备时间口径：${esc(x.time_rule)}<br>来源：${esc((x.source_ids||[]).join('、'))} · ${esc(x.status)}。此处为连续流功能区映射；通过时间τ = ρAL/ṁ由几何决定，原批次设备案例时间单独作为参考，不赋给床段。</div>`:'';}
function parallelEvidence(m){const ids=[...(m.skimmingEnabled?['SKIM']:[]),...(m.blowingMode&&m.blowingMode!=='none'?['AR']:[]),...(m.powderKgMin>0?['POWDER']:[]),...(m.heatingEnabled?['TDHEAT']:[])];return ids.length?`<p class="help">并行操作目录参考：${ids.map(id=>{const x=catalogue.find(x=>x.equipment_id===id);return x?`${esc(id)} · ${esc(x.name)} [${esc((x.source_ids||[]).join('、'))}]`:esc(id)}).join('；')}。目录说明用途，不提供本连续床的通用去除率或热效率。</p>`:'';}
function diagram(g){return `<section class="panel stage-panel" aria-label="电炉到连铸机连续精炼床框架"><div class="stage-head sectionbar"><strong>01 / 连续流精炼床框架</strong><span class="tag">主体分区串联 · 辅助操作并行</span></div><div class="scroll"><div class="schematic connected parallel-layout" style="min-width:${Math.max(1050,state.modules.length*260+550)}px"><div class="machine furnace"><svg role="img" aria-label="电炉出钢口与槽体直接相接" viewBox="0 0 160 200"><path d="M15 75h100l-11 70H28z" fill="#4b6868"/><path d="M12 74h110v14H12z" fill="#91aaa0"/><path d="M35 53v38m30-53v53m30-38v38" stroke="#334c4e" stroke-width="8"/><path d="M24 92h81l-8 31H30z" fill="#e99c51"/><path d="M104 113l21-13h35" stroke="#56756b" stroke-width="26"/><path d="M104 110l21-10h35" stroke="#e9934e" stroke-width="14"/><circle cx="131" cy="100" r="9" fill="#fff" stroke="#207b70" stroke-width="3"/><path d="M125 100h12m-6-6v12" stroke="#207b70" stroke-width="2"/><path d="M32 145v20m67-20v20" stroke="#4b6868" stroke-width="7"/></svg><p>电炉 EAF · 出钢口</p></div><div class="bed-assembly"><div class="zone-grid">${state.modules.map((m,i)=>`<div class="zone-column" data-zone="${i}" style="--grow:${m.lengthM}">${upperControls(m,i)}<div class="zone bed-zone"><div class="zone-title"><span>第 ${i+1} 区</span><button data-edit="${i}" aria-label="编辑第${i+1}区参数">参数</button><button class="danger" data-remove="${i}" aria-label="删除第${i+1}区">删除</button></div><label>主体精炼设备<select aria-label="槽上第${i+1}区设备" data-path="modules.${i}.type" data-text>${options(types,m.type)}</select></label>${field(`modules.${i}.lengthM`,`第${i+1}区床长 / m`,m.lengthM)}<span class="zone-time" data-stage-time="${i}">${num(g.residenceMin*m.lengthM/state.geometry.lengthM)} min 连续通过</span></div>${lowerControls(m,i)}</div>`).join('')}<div class="zone-column remainder-column" data-remainder style="--grow:${Math.max(.1,state.geometry.lengthM-state.modules.reduce((s,m)=>s+m.lengthM,0))}"><div class="parallel-top empty-overlay"><span>扒渣、顶吹／底吹：附着在各区上方</span></div><div class="zone bed-zone add-zone"><select aria-label="槽上选择新增设备" id="diagram-addtype" ${!catalogue.length?'disabled':''}>${options(types,'LF')}</select><button class="primary" data-open-add ${!catalogue.length?'disabled':''}>${catalogue.length?'＋ 添加主体分区':'载入设备目录…'}</button><small>未分配床长保留连续输送</small></div><div class="parallel-bottom empty-overlay"><span>补热：附着在各区下方</span></div></div></div><p class="help" data-flow-caption>${num(state.geometry.lengthM)} m 连续床 · 平均流速 ${num(g.velocityMps,4)} m/s · 示意图不按比例</p></div><div class="machine caster"><svg role="img" aria-label="槽体出口与连铸机中间包直接相接" viewBox="0 0 160 200"><path d="M0 100h56" stroke="#56756b" stroke-width="26"/><path d="M0 100h56" stroke="#e9934e" stroke-width="14"/><path d="M43 98h88l-9 29H53z" fill="#7d9990"/><path d="M53 104h68l-5 13H58z" fill="#e99c51"/><path d="M87 127v17q0 31 35 31h31" stroke="#c05c32" stroke-width="13" fill="none"/><g fill="#a7bcb2" stroke="#506f6a" stroke-width="3"><circle cx="68" cy="143" r="7"/><circle cx="106" cy="143" r="7"/><circle cx="97" cy="186" r="7"/><circle cx="126" cy="158" r="7"/><circle cx="145" cy="188" r="7"/></g></svg><p>连续出口 → 连铸机 CC</p></div></div></div><div class="flow-control"><strong>出钢流量控制器</strong>${field('flowTph','质量流量 / t·h⁻¹',state.flowTph)}</div><div class="flow-basis">速度来自钢水处理流量：u = ṁ / (ρA)，本段通过时间 = L / u = ρAL / ṁ。当前 ${num(state.flowTph)} t/h → ${num(g.flowM3h)} m³/h → ${num(g.velocityMps,5)} m/s。该速度只描述流动，是否达到精炼目标还要核对反应能力。</div></section>`;}
function metric(title,value,unit,hint=''){return `<div class="metric"><small>${title}</small><strong>${num(value)}</strong><span>${unit}</span>${hint?`<em>${hint}</em>`:''}</div>`}
function heatingExplanation(m){const r=evaluate(state),s=(r.stages||[]).find(x=>x.id===m.id)||{};return `η = 钢液有效得热 / 装置输入能量；不是由流量单独确定。<br>η = [ṁcₚ(T出实测−T入实测)+Q损] / ${m.heatingMethod==='powder'?'实际反应放热功率':'P输入'}。η之外仍需计算热损，不能把钢液净温升当作装置效率。<br>当前流量 ${num(state.flowTph)} t/h：仅加热贡献 +${num(s.heatingDeltaTK)} K；无加热温差 ${num(s.noHeatDeltaTK)} K；净温差 ${num(s.deltaTK)} K；出口 ${num(s.out?.T)} °C。<br>保持入口温度所需输入 ${num(s.holdingInputKW)} kW；由两端实测温度反算η ${num(s.inferredHeatEfficiency)}${s.inferredEfficiencyValid===false?'（超出0–1，测量或损失边界需复核）':''}。`}
function moduleUI(m,i){const top=['top','combined'].includes(m.blowingMode),bottom=['bottom','combined'].includes(m.blowingMode);return `<article class="module" data-owner-module="${esc(m.id)}"><div class="sectionbar"><h3>${String(i+1).padStart(2,'0')} · ${esc(typeName(m.type))}</h3><div class="actions"><button data-up="${i}" ${i===0?'disabled':''}>↑ 上移</button><button data-down="${i}" ${i===state.modules.length-1?'disabled':''}>↓ 下移</button><button class="danger" data-remove="${i}">移除</button></div></div><details class="catalogue-disclosure"><summary>设备功能与文献来源</summary>${equipmentNote(m)}${parallelEvidence(m)}</details><div class="module-fields">${selector(`modules.${i}.type`,'精炼手段',types,m.type)}${field(`modules.${i}.lengthM`,'占用床长 / m',m.lengthM)}${selector(`modules.${i}.flowModel`,'连续流动近似',{PFR:'理想活塞流 PFR',CSTR:'理想全混流 CSTR'},m.flowModel)}${selector(`modules.${i}.species`,'本段预测指标',{'':'不求解化学反应',S:labels.S,C:labels.C,Odiss:labels.Odiss,TO:labels.TO,H:labels.H},m.species)}${field(`modules.${i}.target`,'本段目标（同指标单位）',m.target)}</div><details><summary>反应动力学与文献适用性</summary><p class="help">k必须代表本床工况；顶吹、底吹、扒渣或气量改变不会自动生成新的k，需由实测或适用模型标定。</p><div class="module-fields">${field(`modules.${i}.kPerMin`,'k / min⁻¹',m.kPerMin)}${field(`modules.${i}.equilibrium`,'平衡 / 极限浓度（同指标单位）',m.equilibrium)}${field(`modules.${i}.availableOxygenKgT`,m.species==='C'?'分配给脱碳反应的氧 / kg·t⁻¹':'可用于本段反应的氧 / kg·t⁻¹',m.availableOxygenKgT)}${['VD','RH','RHOB','VAD'].includes(m.type)?`<label>已配置独立密封真空舱<select data-path="modules.${i}.sealedVacuum" data-bool>${options({'false':'否 / 开放槽','true':'是（仍需标定）'},String(!!m.sealedVacuum))}</select></label>`:''}<label>证据 / 标定记录 ID<input data-evidence="${i}" value="${esc((m.evidenceIds||[]).join(', '))}" placeholder="案例ID或独立标定记录"></label></div></details><details><summary>喷吹、扒渣与物料参数</summary><div class="module-fields">${boolSelect(`modules.${i}.skimmingEnabled`,'并行扒渣',m.skimmingEnabled)}${m.skimmingEnabled?field(`modules.${i}.slagRemovalKgT`,'扒出渣量 / kg·t⁻¹',m.slagRemovalKgT)+field(`modules.${i}.coveredFraction`,'本段有效渣覆盖率 / 0–1（未指定沿用全局）',m.coveredFraction):''}${selector(`modules.${i}.blowingMode`,'喷吹方法',{none:'无喷吹',top:'顶吹',bottom:'底吹',combined:'顶底复吹'},m.blowingMode||'none')}${top?selector(`modules.${i}.topGas`,'顶吹气体',gasOptions,m.topGas||'Ar')+field(`modules.${i}.topGasNLmin`,'顶吹标况气量 / NL·min⁻¹',m.topGasNLmin):''}${bottom?selector(`modules.${i}.bottomGas`,'底吹气体',gasOptions,m.bottomGas||'Ar')+field(`modules.${i}.bottomGasNLmin`,'底吹标况气量 / NL·min⁻¹',m.bottomGasNLmin):''}${selector(`modules.${i}.powderInjection`,'喷粉位置',{top:'顶喷',bottom:'底喷'},m.powderInjection||'top')}${field(`modules.${i}.powderKgMin`,'粉料速率 / kg·min⁻¹',m.powderKgMin)}${field(`modules.${i}.alloyKgT`,'合金投入 / kg·t⁻¹',m.alloyKgT)}</div><p class="help">扒渣、喷吹与主体精炼并行，不增加床长或总通过时间。扒出渣量仅记投入产出账，未建立渣硫/带钢损失网络；不自动获得额外脱硫率。扒渣不会自动推断裸露比例，实际覆盖率需另行指定；本段覆盖率可改变热损边界。N₂可能增氮，O₂可能氧化合金；吹气形式与气种不自动等价为精炼效果。</p></details><details><summary>补热参数与效率校核</summary><div class="module-fields">${boolSelect(`modules.${i}.heatingEnabled`,'是否需要补热',m.heatingEnabled)}${m.heatingEnabled?`${selector(`modules.${i}.heatingMethod`,'补热手段',{induction:'电磁 / 感应',plasma:'等离子',powder:'喷粉化学补热',other:'其他'},m.heatingMethod||'induction')}${field(`modules.${i}.heatKW`,'输入功率 / kW',m.heatKW)}${field(`modules.${i}.heatEfficiency`,'钢液有效热效率 / 0–1',m.heatEfficiency)}${field(`modules.${i}.measuredInletC`,'本段入口实测温度 / °C（可选）',m.measuredInletC)}${field(`modules.${i}.measuredOutletC`,'本段出口实测温度 / °C（可选）',m.measuredOutletC)}${m.heatingMethod==='powder'?`${field(`modules.${i}.reactionMJkg`,'粉料反应焓 / MJ·kg⁻¹',m.reactionMJkg)}${field(`modules.${i}.reactedFraction`,'实际转化比例 / 0–1',m.reactedFraction)}${field(`modules.${i}.oxygenKgPerKg`,'化学计量耗氧 / kgO·kg粉⁻¹',m.oxygenKgPerKg)}${field(`modules.${i}.heatAvailableOxygenKgT`,'分配给喷粉补热的氧 / kg·t⁻¹',m.heatAvailableOxygenKgT)}${m.species==='C'?field(`modules.${i}.totalAvailableOxygenKgT`,'本段总可用氧预算 / kg·t⁻¹',m.totalAvailableOxygenKgT):''}<p class="help">脱碳与喷粉可在同段并行，但须分别分配氧；脱碳配额＋补热配额不得超过本段总可用氧。供气体积不自动等于可用氧量。关闭补热后不消耗补热氧预算。</p>`:''}`:'<p>未启用补热；该段有效加热计0，仍持续散热。</p>'}<div class="eta-definition" data-module-heat="${m.id}">${heatingExplanation(m)}</div></div><p class="help">补热与主体精炼使用同一段通过时间。有效热效率与反应参数需适用数据；不提供未经标定的通用设备保证值。</p></details></article>`;}
function goalUI(r){return `<section class="panel goal-panel"><div class="sectionbar"><h2>目标设定</h2><button data-save-plan>保存当前搭配作对比</button></div><p class="help">目标是研究输入，不代表牌号标准。${Object.entries(state.targets||{}).map(([k,v])=>`${esc(labels[k])} ≤ ${num(v)}`).join(' · ')}</p><details><summary>编辑终点目标与出口温度</summary><div class="fields">${Object.entries(state.targets||{}).map(([k,v])=>field(`targets.${k}`,labels[k]+' 终点上限',v)).join('')}${field('targetOutletC','目标出口温度 / °C（可选）',state.targetOutletC??null)}</div></details><div id="plan-summary">${planningUI(r)}</div><div id="saved-plans">${savedPlansUI()}</div>${state.parallelMigrationNotes?.length?`<details><summary>旧版辅助分区迁移说明</summary><p class="help">${state.parallelMigrationNotes.map(esc).join('<br>')} 原操作设置仍保留在导出的方案归档中。</p></details>`:''}</section>`;}

function planningUI(r){const p=summarizePlan(state,r);return `<div class="result-note"><strong>${esc(p.statusLabel||'当前搭配能力核对')}</strong><br>${esc(p.routeLabel||state.modules.map(m=>m.type).join(' → ')||'尚未添加主体分区')}<br>当前处理流量 ${num(state.flowTph)} t/h；主体占用 ${num(state.modules.reduce((a,m)=>a+m.lengthM,0))} / ${num(state.geometry.lengthM)} m；并行补热 ${state.modules.filter(m=>m.heatingEnabled).length} 处、扒渣 ${state.modules.filter(m=>m.skimmingEnabled).length} 处、喷吹 ${state.modules.filter(m=>m.blowingMode&&m.blowingMode!=='none').length} 处。<br>已知单段目标的局部能力上限 ${capacityNum(p.capability?.knownLimitTph)} t/h；${p.capability?.unknown?'仍有能力未知项，不能作为整床达标产能。':'仅为当前参数下的条件计算，不是设备保证。'}</div><div class="tablewrap"><table><thead><tr><th>整床目标</th><th>承担区段</th><th>入口 → 预测终点</th><th>目标</th><th>需净去除 / kg·t⁻¹</th><th>当前组合判断</th></tr></thead><tbody>${(p.objectives||[]).map(o=>`<tr><td>${esc(o.label||o.key)} / ${esc(o.unit)}</td><td>${(o.stages||[]).length?(o.stages||[]).map(i=>`${i+1} · ${esc(state.modules[i]?.type||'未知区段')}`).join('、'):'未配置'}</td><td>${num(o.inlet)} → ${num(o.final)}</td><td>${num(o.target)}</td><td>${num(o.removalNeededKgT)}</td><td>${o.status==='pass'?'满足数值目标':o.status==='fail'?'未满足':'未知 / 待补参数'}</td></tr>`).join('')}</tbody></table></div><p class="help">需净去除量是入口至目标的元素质量差，不是应加入的粉料／合金量；实际配方还需要化学计量、收得率和反应模型。</p><div class="result-note">出口温度目标 ${num(p.thermal?.targetOutletC)} °C；预测 ${num(p.thermal?.finalC)} °C；目标温度差 ${num(p.thermal?.gapK)} K；还需额外钢液有效得热 ${num(p.thermal?.requiredAdditionalDeliveredKW)} kW。缺少热边界时不补算。</div>${p.requiredInputs?.length?`<details open><summary>补齐这些参数才能判断整床能力</summary><ul>${p.requiredInputs.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>`:''}${p.flowScenarios?.length?`<details><summary>相同设备、气粉与功率下的流量情景</summary><div class="tablewrap"><table><thead><tr><th>流量 / t/h</th><th>通过 / min</th><th>满足 / 未满足 / 未知</th><th>出口 °C</th></tr></thead><tbody>${p.flowScenarios.map(x=>`<tr><td>${num(x.flowTph)}</td><td>${num(x.throughMin)}</td><td>${x.passCount} / ${x.failCount} / ${x.unknownCount}</td><td>${num(x.finalT)}</td></tr>`).join('')}</tbody></table></div><p class="help">固定当前投入速率与功率的条件情景，不是优化结果，也不是通过能力保证。</p></details>`:''}<p class="help">${(p.issues||[]).map(esc).join('<br>')}</p>`;}
function savedPlansUI(){let list=[];try{list=JSON.parse(localStorage.getItem('bed-plan-comparisons')||'[]')}catch{}return list.length?`<h3>搭配对比（本地保存）</h3><div class="tablewrap"><table><thead><tr><th>搭配</th><th>流量 / t/h</th><th>通过 / min</th><th>已知局部能力 / t/h</th><th>出口 °C</th><th>目标满足 / 未满足 / 未知</th><th></th></tr></thead><tbody>${list.map((x,i)=>`<tr><td>${esc(x.routeLabel||'空床')}<small>${esc(x.at)}</small></td><td>${num(x.flowTph)}</td><td>${num(x.timeMin)}</td><td>${x.knownLimitLabel||capacityNum(x.knownLimitTph)}</td><td>${num(x.finalT)}</td><td>${x.passCount??'—'} / ${x.failCount??'—'} / ${x.unknownCount??'—'}</td><td><button data-delete-plan="${i}">删除</button></td></tr>`).join('')}</tbody></table></div><p class="help">快照记录当时的输入与计算状态；缺参数的能力不当作零，保存不等于工业验证。</p>`:'';}
function render(){document.querySelectorAll('#app details').forEach(d=>{const key=disclosureKey(d);if(d.open)openDisclosures.add(key);else openDisclosures.delete(key);});let r;try{r=evaluate(state)}catch(e){r={valid:false,errors:[e.message]}}const g=r.geometry||{};$('#app').innerHTML=`<div class="titlebar"><div><div class="eyebrow">STEEL REFINING WORKBENCH</div><h1>连续精炼床设计工作台</h1><p class="lead">设定目标 → 搭建区段 → 核对能力。空白参数保留未知。</p></div><div class="actions"><button data-export>导出方案 JSON</button><button data-import>导入方案</button><button data-reset>恢复设计示例</button><input type="file" accept="application/json,.json" id="import" hidden></div></div>${diagram(g)}${goalUI(r)}<div class="metrics" data-geometry-metrics>${metric('截面积',g.areaM2,'m²')}${metric('槽内钢液体积',g.volumeM3,'m³')}${metric('钢液存量',g.inventoryT,'t')}${metric('连续通过时间',g.residenceMin,'min','M / ṁ；持续流动，无停车')}${metric('入口处理量',state.flowTph,'t/h','设定流量；不是达标产能保证')}</div><div class="notice">数据包未提供本连续床的实测反应系数、气粉配方与加热效率。几何默认值和入口成分为设计示例；空白参数表示未知，文献案例保留原设备、钢种、吨位和单位，不自动外推。</div><div class="grid2"><section class="panel"><h2>02 / 月牙截面与几何</h2><div class="geometry-wrap"><div class="fields">${field('geometry.lengthM','精炼床总长 / m',state.geometry.lengthM)}<label class="range-field">直接设置截面积 / m²<output data-area-output>${num(g.areaM2,6)}</output><input aria-label="直接设置截面积 / m²" type="range" min="0.001" max="${Math.max(3,g.areaM2||0)}" step="0.001" data-area value="${g.areaM2??.001}"><small>同比缩放 R、h，保持截面形状</small></label>${field('geometry.radiusM','圆弧半径 R / m',state.geometry.radiusM)}${field('geometry.depthM','液深 h / m',state.geometry.depthM)}${field('geometry.densityKgM3','钢液密度 / kg·m⁻³',state.geometry.densityKgM3)}</div><button class="section-svg" data-geometry title="查看月牙截面定义" style="border:0;background:none;padding:0"><svg role="img" aria-label="月牙形开口圆弓截面，点击查看几何定义" viewBox="0 0 150 140"><path d="M14 60 Q75 160 136 60" fill="#e8a05c" stroke="#56756b" stroke-width="8"/><path d="M14 60h122" stroke="#ba6538" stroke-width="3"/><path d="M75 60v48" stroke="#fff" stroke-width="2"/><text x="84" y="93" font-size="13" fill="#fff">h</text><text x="25" y="35" font-size="12" fill="#62757a">圆弓形 / 月牙槽底</text></svg></button></div><p class="help">将“月牙”定义为开口圆弓形液体截面。面积由 R、h 联动计算；液深须小于或等于半径。液面宽 ${num(g.topWidthM)} m；接触弧长 ${num(g.wettedPerimeterM)} m。</p><div class="result-note">液面面积 ${num(g.topAreaM2)} m² · 耐火材料接触面积 ${num(g.wallAreaM2)} m²（计算口径见公式）</div></section><section class="panel"><div class="sectionbar"><h2>03 / 入口成分记录</h2><button data-record>记录当前来料</button></div><div class="fields wide">${Object.entries(state.inlet).map(([k,v])=>field(`inlet.${k}`,labels[k]||k,v)).join('')}</div><p class="help">质量百分数与 ppm 分开；溶解氧和总氧独立输入。来料记录仅保存在本浏览器，不上传到服务器。</p><div class="records" id="records"></div></section></div><section class="panel" id="module-editor"><div class="sectionbar"><h2>区段参数编辑</h2><div class="actions"><select id="addtype" aria-label="选择要添加的精炼手段">${options(types,'LF')}</select><button class="primary" data-add-selected>＋ 添加模块</button></div></div><p class="help">每段床长0.5–3 m、每档0.5 m；辅助操作并行，不另占床长。此处为连续功能区映射，不代表实际LF/RH/VD炉体尺寸。</p>${state.modules.length?modulePicker()+moduleUI(state.modules[selectedIndex()],selectedIndex()):'<div class="empty">精炼床尚未添加处理区。点击上方按钮添加第一段。</div>'}</section><section class="panel" id="thermal-boundaries"><h2>热损与保温边界</h2><p class="help">表面覆盖、裸露与接触面积分别核算。热流密度和比热需来自适用工况或校准；不将旧网页的矩形槽默认参数自动移植到月牙截面。</p><div class="fields">${field('cpKJkgK','钢液比热 / kJ·kg⁻¹·K⁻¹',state.cpKJkgK)}${field('liquidusC','液相线参考 / °C',state.liquidusC)}${field('thermal.coveredFraction','渣覆盖面积比例 / 0–1',state.thermal.coveredFraction)}${field('thermal.coveredFluxKWm2','覆盖区热流密度 / kW·m⁻²',state.thermal.coveredFluxKWm2)}${field('thermal.bareFluxKWm2','裸露区热流密度 / kW·m⁻²',state.thermal.bareFluxKWm2)}${field('thermal.wallFluxKWm2','耐材接触热流密度 / kW·m⁻²',state.thermal.wallFluxKWm2)}</div><p class="help"><a href="./heating.html">打开详细传导、辐射、对流与加热效率核算 ↗</a> · 该子页为独立矩形槽模型，几何和参数不会自动同步。</p></section><div class="sectionbar" style="margin-top:26px"><h2>06 / 整体能力与分段结果</h2><span class="status">${esc(status)}</span></div><div id="results">${resultUI(r)}</div><section class="panel"><h2>07 / 公式与计算口径</h2><div class="formula">A = R² arccos((R−h)/R) − (R−h)√(2Rh−h²)<br>V = AL；M = ρV；连续通过时间 τ = M / ṁ；平均流速 u = ṁ / (ρA)<br>PFR：c出 = c* + (c入−c*) exp(−kτ)；CSTR：c出 = c* + (c入−c*) / (1+kτ)<br>连续气体单耗 = Q气 / ṁ钢；粉料单耗 = ṁ粉 / ṁ钢；加热电耗 = P输入 / ṁ钢<br>Q损 = A覆盖q覆盖 + A裸露q裸露 + A接触q接触；ΔT = (P有效−Q损) / (ṁ钢 cₚ)</div><p class="help">这些公式是守恒与理想反应器框架。连续通过时间不能代表短路流、死区及夹杂物连续通过时间分布；PFR/CSTR 为两种理想化情景，不是已验证的实际流态。热模型为稳态集中参数，未求启动耐材蓄热、反应热与相变。</p></section><section class="panel"><div class="sectionbar"><h2>08 / 合并的数据包参考</h2><a href="./evidence/index.html">打开完整证据库 ↗</a></div><div id="evidence"><p class="help">载入原始案例与来源…</p></div></section><dialog id="geometry-dialog"><h2>月牙截面定义</h2><p>本页采用开口圆弓形：半径 R 的圆被液面弦截出高度 h 的液体区域。输入 R、h 后，截面积、液面宽度和接触弧长必须一起变化，不允许独立改动截面积破坏几何关系。</p><p>“月牙”如果指两个圆弧之间的非圆弓槽型，需要另外提供内外半径或截面坐标；当前页面不会将其当成同一形状。</p><button data-close-dialog>关闭</button></dialog>`;renderRecords();renderEvidence();organizeWorkbench(r);}
function resultUI(r){if(!r.valid)return `<div class="error">${(r.errors||['输入无效']).map(esc).join('<br>')}</div>`;const t=r.totals||{};return `<section class="panel"><div class="tablewrap"><table><thead><tr><th>工序</th><th>占用床长 / m</th><th>连续通过时间 / min</th><th>预测指标 / 入 → 出</th><th>达到目标所需 / min</th><th>能力 / t·h⁻¹</th></tr></thead><tbody>${(r.stages||[]).map((s,i)=>{const m=state.modules.find(m=>m.id===s.id)||{type:s.type,lengthM:s.lengthM,species:s.species},before=s.inlet??s.in??s.before??{},after=s.outlet??s.out??s.after??{};return `<tr><td>${i+1} · ${esc(typeName(m.type))}</td><td>${num(m.lengthM)}</td><td>${num(s.residenceMin??s.timeMin??s.time)}</td><td>${m.species?`${esc(m.species)} / ${num(before[m.species]??s.inletValue)} → ${num(after[m.species]??s.outletValue)}`:'无指定化学处理'}</td><td>${s.requiredTimeMin===Infinity?'不可达到':num(s.requiredTimeMin)}</td><td>${capacityNum(s.throughputLimitTph??s.maxThroughputTph)}</td></tr>`}).join('')||'<tr><td colspan="6">尚无处理模块；仅核算几何与流量。</td></tr>'}</tbody></table></div><div class="total-grid"><div><small>总连续通过时间 / min</small><strong>${num(r.geometry?.residenceMin)}</strong><p>连续流过各段，不增加停车或等待时间</p></div><div><small>总热损 / kW</small><strong>${num(t.lossKW??t.heatLossKW??r.thermal?.lossKW)}</strong><p>热流密度未知则无法求解</p></div><div><small>有效加热 / kW</small><strong>${num(t.deliveredKW)}</strong><p>输入功率 × 钢液有效效率</p></div><div><small>出口钢温 / °C</small><strong>${num(r.final?.T)}</strong><p>温度边界不全时显示未知</p></div></div><div class="result-note">按已指定本段目标反算的单段局部能力上限：<strong>${capacityNum(r.throughputLimitTph??t.throughputLimitTph)} t/h</strong>。${(r.unknownCapacity??t.unknownCapacity)?'部分处理区缺少目标或动力学，整体达标能力未知。':'仅适用于已计算的指标；不代表设备保证产能。'}<br>液相线检查：${r.phaseValid===true?'出口高于已输入液相线':r.phaseValid===false?'低于液相线，液态模型失效':'液相线或温度未知，不能判定'}。</div><h3 style="margin-top:22px">连续消耗账</h3><div class="tablewrap"><table><thead><tr><th>工序</th><th>气体</th><th>气 / Nm³·h⁻¹</th><th>气 / Nm³·t⁻¹</th><th>粉 / kg·h⁻¹</th><th>粉 / kg·t⁻¹</th><th>合金 / kg·t⁻¹</th><th>输入能量 / kWh·t⁻¹</th></tr></thead><tbody>${(r.stages||[]).filter(s=>s.id!=='unallocated').map((s,i)=>`<tr><td>${i+1} · ${esc(typeName(s.type))}</td><td>${(s.gasStreams||[]).map(g=>`${esc(g.position==='top'?'顶吹':g.position==='bottom'?'底吹':'原记录')} ${esc(g.gas)}`).join(' + ')||'无喷吹'}</td><td>${num(s.gasNm3h)}</td><td>${num(s.gasNm3T)}</td><td>${num(s.powderKgh)}</td><td>${num(s.powderKgT)}</td><td>${num(s.alloyKgT)}</td><td>${num(s.energyKWhT)}</td></tr>`).join('')}</tbody></table></div><div class="result-note">整体扒出渣：${num(t.slagRemovalKgh)} kg/h · ${num(t.slagRemovalKgT)} kg/t；粉料：${num(t.powderKgh)} kg/h · ${num(t.powderKgT)} kg/t；合金：${num(t.alloyKgh)} kg/h · ${num(t.alloyKgT)} kg/t；电耗：${num(t.energyKWhT)} kWh/t。<br>分气种供气：${Object.entries(t.gasByType||{}).map(([k,v])=>`${esc(k)} ${num(v)} Nm³/h`).join('；')}。未填写的投入不当作零；未包含配方和组分平衡的投入不自动改变终点。</div><h3>统一目标检查</h3><div class="tablewrap"><table><thead><tr><th>指标</th><th>终点</th><th>目标上限</th><th>判断</th></tr></thead><tbody>${(r.checks||[]).map(c=>`<tr><td>${esc(labels[c.species]||c.species)}</td><td>${num(c.value)}</td><td>${num(c.max)}</td><td class="${c.pass===true?'pass':'fail'}">${c.pass===null?'未知，不能判定':c.pass?'满足数值约束':'未满足'}</td></tr>`).join('')}</tbody></table></div><h3>终点指标</h3><div class="metrics">${Object.entries(r.final||{}).filter(([k])=>labels[k]&&k!=='T').map(([k,v])=>metric(labels[k],v,'',v===null?'缺少动力学或上游状态':'模型值，非产品认证')).join('')}</div><div class="notice">${[...(r.warnings||[]),...(r.stages||[]).flatMap(s=>s.notes||[])].map(esc).join('<br>')||'输出是理想反应器估算，尚未经过本连续床的独立工业验证。'}</div></section>`}
function renderRecords(){let records=[];try{records=JSON.parse(localStorage.getItem('bed-inlet-records')||'[]')}catch{}$('#records').innerHTML=records.slice(-5).map((r,i)=>`<button data-load-record="${records.length-Math.min(5,records.length)+i}">${esc(r.name)} · ${esc(r.at)}</button>`).join('');}
function renderEvidence(){if(!evidence)return;const list=Array.isArray(evidence)?evidence:(evidence.groups||evidence.cases||evidence.references||evidence.records||[]);$('#evidence').innerHTML=`<p class="help">以下为原设备参考；点击查看完整数据时，须核对原单位、数据角色与适用域。没有连续床专用实测 k 与热效率，不自动载入为配方。</p><div class="actions">${(evidence.safe_imports||[]).map((x,i)=>`<button data-safe-import="${i}">采用物性参考 ${esc(x.observation_id)}：${esc(x.value)} ${esc(x.unit)}</button>`).join('')}</div><p class="help">采用物性只表示你选择该文献模型输入；密度和比热来自不同案例，不构成同一连续床验证数据。</p><div class="evidence-grid">${list.slice(0,8).map(c=>`<article class="evidence-card"><code>${esc(c.case_id||c.caseId||c.id||c.source_id||'参考')}</code><h3>${esc(c.label||c.title||c.name||c.process||'原始工况')}</h3><p>${esc(c.warning||c.boundary||c.limitations||c.context||'查看原工况、参数口径与适用边界。')}</p><div class="tablewrap"><table><tbody>${(c.observation_ids||[]).slice(0,5).map(id=>{const o=(evidence.observations||[]).find(x=>x.observation_id===id);return o?`<tr><td><code>${esc(id)}</code><br>${esc(o.parameter)}</td><td>${o.value!=null?num(o.value,6):`${num(o.lower_value,6)}–${num(o.upper_value,6)}`} ${esc(o.unit)}<br><small>${esc(o.quantity_role)} · ${esc(o.evidence_tag)}</small></td></tr>`:''}).join('')}</tbody></table></div><a href="./evidence/index.html">核对完整参数与来源 ↗</a></article>`).join('')}</div><details><summary>本页引用的结构化参考记录</summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px">${esc(JSON.stringify(evidence,null,2))}</pre></details>`;}
function setPath(path,value){const keys=path.split('.');let obj=state;for(const k of keys.slice(0,-1))obj=obj[k];obj[keys.at(-1)]=value;}
function liveUpdate(el){document.querySelectorAll('#app details').forEach(d=>{const key=disclosureKey(d);if(d.open)openDisclosures.add(key);else openDisclosures.delete(key);});const r=evaluate(state),g=r.geometry||{};document.querySelectorAll('[data-output]').forEach(o=>{const keys=o.dataset.output.split('.');let v=state;for(const key of keys)v=v?.[key];o.textContent=num(v,6);});document.querySelectorAll('input[type="range"][data-path]').forEach(x=>{if(x!==el){const keys=x.dataset.path.split('.');let v=state;for(const key of keys)v=v?.[key];if(v!=null)x.value=v;}});$('#results').innerHTML=resultUI(r);if($('#plan-summary'))$('#plan-summary').innerHTML=planningUI(r);document.querySelectorAll('[data-module-heat]').forEach(x=>{const m=state.modules.find(m=>m.id===x.dataset.moduleHeat);if(m)x.innerHTML=heatingExplanation(m);});const metrics=$('[data-geometry-metrics]');if(metrics)metrics.innerHTML=metric('截面积',g.areaM2,'m²')+metric('槽内钢液体积',g.volumeM3,'m³')+metric('钢液存量',g.inventoryT,'t')+metric('连续通过时间',g.residenceMin,'min','M / ṁ；持续流动，无停车')+metric('入口处理量',state.flowTph,'t/h','设定流量，非达标产能保证');document.querySelectorAll('[data-zone]').forEach(z=>z.style.setProperty('--grow',state.modules[+z.dataset.zone].lengthM));document.querySelectorAll('[data-stage-time]').forEach(z=>{const i=+z.dataset.stageTime;z.textContent=num(g.residenceMin*state.modules[i].lengthM/state.geometry.lengthM)+' min 连续通过';});const rem=$('[data-remainder]');if(rem)rem.style.setProperty('--grow',Math.max(.1,state.geometry.lengthM-state.modules.reduce((s,m)=>s+m.lengthM,0)));const caption=$('[data-flow-caption]');if(caption)caption.textContent=num(state.geometry.lengthM)+' m 连续床 · 平均流速 '+num(g.velocityMps,4)+' m/s · 示意图不按比例';const area=$('[data-area-output]');if(area)area.textContent=num(g.areaM2,6);document.querySelectorAll('#app details').forEach(d=>{if(openDisclosures.has(disclosureKey(d)))d.open=true;});save();}
$('#app').addEventListener('input',e=>{const el=e.target;if(el.type!=='range')return;if(el.hasAttribute('data-area')){const g=evaluate(state).geometry;if(g?.areaM2>0){const scale=Math.sqrt(el.valueAsNumber/g.areaM2);state.geometry.radiusM*=scale;state.geometry.depthM*=scale;}}else if(el.dataset.path)setPath(el.dataset.path,el.valueAsNumber);status='拖动中实时计算；钢水连续通过各区段。';liveUpdate(el);});
$('#app').addEventListener('change',async e=>{const el=e.target;if(el.type==='range'){save();render();return;}if(el.id==='import'){try{const file=el.files[0];if(!file)return;const data=JSON.parse(await file.text()),candidate=migrateParallel(data.config||data);const check=evaluate(candidate);if(!check.valid)throw new Error(check.errors.join('；'));state=candidate;save();status='方案已导入。';render()}catch(err){alert('导入失败：'+err.message)}return;}if(el.hasAttribute('data-area')){const area=el.valueAsNumber,old=evaluate(state).geometry?.areaM2;if(Number.isFinite(area)&&area>0&&old>0){const scale=Math.sqrt(area/old);state.geometry.radiusM*=scale;state.geometry.depthM*=scale;save();status='已按截面积同比缩放圆弓截面。';render()}else{el.setCustomValidity('截面积必须为正有限数值');el.reportValidity()}return;}if(el.dataset.evidence!==undefined){state.modules[+el.dataset.evidence].evidenceIds=el.value.split(',').map(s=>s.trim()).filter(Boolean);save();return;}if(el.matches('[data-flow-range]')){state.flowTph=el.valueAsNumber;save();status='已按新流量重新核算。';render();return;}if(el.hasAttribute('data-module-picker')){selectedModuleId=el.value;render();return;}if(el.dataset.path&&el.dataset.path.startsWith('modules.'))selectedModuleId=state.modules[+el.dataset.path.split('.')[1]]?.id;if(el.dataset.path&&el.dataset.path.startsWith('modules.')&&el.dataset.path.endsWith('.type')){const i=+el.dataset.path.split('.')[1],fresh=freshModule(el.value);state.modules[i]={...state.modules[i],type:fresh.type,species:fresh.species,kPerMin:null,equilibrium:null,target:null,evidenceIds:fresh.evidenceIds};save();render();return;}if(el.dataset.path){const keys=el.dataset.path.split('.');let obj=state;for(const k of keys.slice(0,-1))obj=obj[k];obj[keys.at(-1)]=el.dataset.bool!==undefined?el.value==='true':el.dataset.text!==undefined?el.value:(el.value===''?null:el.valueAsNumber);save();status='已按当前输入重新核算。';render();}});
$('#app').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.wbView){uiView=b.dataset.wbView;switchWorkbench();return;}if(b.dataset.edit!==undefined){selectedModuleId=state.modules[+b.dataset.edit]?.id;uiView='design';render();$('#module-editor')?.scrollIntoView({block:'start'});return;}if(b.hasAttribute('data-save-plan')){let list=[];try{list=JSON.parse(localStorage.getItem('bed-plan-comparisons')||'[]')}catch{}const r=evaluate(state),p=summarizePlan(state,r);list.push({at:new Date().toLocaleString('zh-CN'),routeLabel:p.routeLabel,flowTph:state.flowTph,timeMin:r.geometry?.residenceMin,knownLimitTph:p.capability?.knownLimitTph,knownLimitLabel:capacityNum(p.capability?.knownLimitTph),finalT:r.final?.T,passCount:(p.objectives||[]).filter(x=>x.status==='pass').length,failCount:(p.objectives||[]).filter(x=>x.status==='fail').length,unknownCount:(p.objectives||[]).filter(x=>x.status==='unknown').length,config:structuredClone(state)});localStorage.setItem('bed-plan-comparisons',JSON.stringify(list.slice(-6)));render();return;}if(b.dataset.deletePlan!==undefined){const list=JSON.parse(localStorage.getItem('bed-plan-comparisons')||'[]');list.splice(+b.dataset.deletePlan,1);localStorage.setItem('bed-plan-comparisons',JSON.stringify(list));render();return;}if(b.dataset.safeImport!==undefined){const entry=evidence.safe_imports[+b.dataset.safeImport];if(entry.field==='rho')state.geometry.densityKgM3=entry.value;if(entry.field==='cp')state.cpKJkgK=entry.value;state.materialEvidence ||= {};state.materialEvidence[entry.field]=entry.observation_id;save();status='已显式采用文献物性参考 '+entry.observation_id+'；不是连续床标定。';render();return;}if(b.dataset.clear){setPath(b.dataset.clear,null);save();render();return;}if(b.dataset.add){state.modules.push(freshModule(b.dataset.add));save();render();return;}if(b.hasAttribute('data-add-selected')){const next=freshModule($('#addtype').value);state.modules.push(next);selectedModuleId=next.id;save();render();return;}if(b.hasAttribute('data-open-add')){if(!catalogue.length)return;const next=freshModule($('#diagram-addtype').value);state.modules.push(next);selectedModuleId=next.id;save();status='已添加处理模块，可在下方编辑参数。';render();return;}if(b.dataset.remove!==undefined){state.modules.splice(+b.dataset.remove,1);save();render();return;}if(b.dataset.up!==undefined||b.dataset.down!==undefined){const i=+(b.dataset.up??b.dataset.down),j=i+(b.dataset.up!==undefined?-1:1);if(j>=0&&j<state.modules.length)[state.modules[i],state.modules[j]]=[state.modules[j],state.modules[i]];save();render();return;}if(b.hasAttribute('data-reset')){state=defaults();save();status='已恢复设计示例；不是实测炉次。';render();return;}if(b.hasAttribute('data-record')){let records=[];try{records=JSON.parse(localStorage.getItem('bed-inlet-records')||'[]')}catch{}records.push({name:'来料 '+(records.length+1),at:new Date().toLocaleString('zh-CN'),inlet:structuredClone(state.inlet)});localStorage.setItem('bed-inlet-records',JSON.stringify(records));renderRecords();return;}if(b.dataset.loadRecord!==undefined){const records=JSON.parse(localStorage.getItem('bed-inlet-records')||'[]');state.inlet=structuredClone(records[+b.dataset.loadRecord].inlet);save();status='已载入历史成分记录。';render();return;}if(b.hasAttribute('data-geometry'))$('#geometry-dialog').showModal();if(b.hasAttribute('data-close-dialog'))$('#geometry-dialog').close();if(b.hasAttribute('data-import'))$('#import').click();if(b.hasAttribute('data-export')){const blob=new Blob([JSON.stringify({schemaVersion:1,exportedAt:new Date().toISOString(),config:state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='continuous-refining-bed.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}});
function disclosureKey(d){const owner=d.closest('[data-owner-module]')?.dataset.ownerModule||d.closest('article')?.querySelector('h3')?.textContent||'';return owner+'::'+(d.querySelector(':scope > summary')?.textContent.trim()||'');}
function selectedIndex(){const found=state.modules.findIndex(m=>m.id===selectedModuleId);return found>=0?found:0;}
function modulePicker(){return `<div class="editor-picker"><label>正在编辑区段<select data-module-picker aria-label="正在编辑区段">${state.modules.map((m,i)=>`<option value="${esc(m.id)}" ${i===selectedIndex()?'selected':''}>第 ${i+1} 区 · ${esc(typeName(m.type))}</option>`).join('')}</select></label><p>一次只编辑一个区段。槽上选设备与长度；下方填写该区段的模型和投入参数。</p></div>`;}
function collapsiblePanel(panel,title,description=''){if(!panel)return null;const d=document.createElement('details');d.className='panel setup-details';d.innerHTML=`<summary>${esc(title)}<small>${esc(description)}</small></summary>`;panel.classList.add('nested-panel');const heading=panel.querySelector('h2');if(heading)heading.hidden=true;d.append(panel);return d;}
function auditUI(){if(!systemAudit)return '<p class="help">完整性审查清单载入中；当前结果为条件评价，非工业认证。</p>';return `<p class="help">${esc(systemAudit.overallLabel||'条件评价原型')} · ${esc(systemAudit.reviewedOn||'')}</p><div class="audit-grid">${(systemAudit.sections||[]).map(x=>`<article><span class="audit-status ${esc(x.status)}">${({implemented:'已实现',conditional:'有条件',missing:'待建设'})[x.status]||esc(x.status)}</span><h3>${esc(x.label)}</h3><p>${esc(x.summary)}</p>${[...(x.missingInputs||[]),...(x.limitations||[])].length?`<details><summary>条件与缺项</summary><ul>${[...(x.missingInputs||[]),...(x.limitations||[])].map(t=>`<li>${esc(t)}</li>`).join('')}</ul></details>`:''}</article>`).join('')}</div>`;}
function organizeWorkbench(r){const app=$('#app'),title=app.querySelector('.titlebar'),diagramPanel=app.querySelector('.stage-panel'),goal=app.querySelector('.goal-panel'),metrics=app.querySelector('[data-geometry-metrics]'),notice=[...app.children].find(x=>x.classList.contains('notice')),grid=app.querySelector('.grid2'),editor=$('#module-editor'),thermal=$('#thermal-boundaries'),results=$('#results'),resultHeading=results?.previousElementSibling,formula=[...app.querySelectorAll('section.panel')].find(x=>x.querySelector('h2')?.textContent.startsWith('07 /')),evidencePanel=$('#evidence')?.closest('section'),dialog=$('#geometry-dialog'),plan=$('#plan-summary'),saved=$('#saved-plans'),saveButton=goal?.querySelector('[data-save-plan]');
 const nav=document.createElement('nav');nav.className='workbench-tabs';nav.setAttribute('aria-label','工作台视图');nav.innerHTML=`<div role="tablist" aria-label="设计步骤">${[['design','01 设计'],['evaluation','02 评价与对比'],['evidence','03 依据与扩展']].map(([key,label])=>`<button id="tab-${key}" role="tab" data-wb-view="${key}" aria-controls="view-${key}">${label}</button>`).join('')}</div><span class="scope-pill">条件模型 · 未工业标定</span>`;
 const panes={};for(const key of ['design','evaluation','evidence']){const pane=document.createElement('div');pane.id='view-'+key;pane.dataset.workbenchView=key;pane.setAttribute('role','tabpanel');pane.setAttribute('aria-labelledby','tab-'+key);panes[key]=pane;}
 const design=panes.design,evaluation=panes.evaluation,basis=panes.evidence;design.append(diagramPanel,metrics,goal);if(!state.modules.length){const guide=document.createElement('div');guide.className='start-guide';guide.innerHTML='<strong>从这里开始</strong><span>1 设定来料与目标</span><span>2 在槽上添加 LF / RH / VD 功能区</span><span>3 打开「评价与对比」核对差距</span>';design.append(guide);}
 if(grid){const sections=[...grid.children],setup=document.createElement('div');setup.className='setup-grid';for(const [i,panel]of sections.entries())setup.append(collapsiblePanel(panel,i===0?'几何与容量':'来料成分与记录',i===0?'长度、月牙截面、密度':'温度、元素、总氧和溶解氧'));design.append(setup);}
 if(editor)design.append(editor);if(thermal)design.append(collapsiblePanel(thermal,'热边界与物性','比热、液相线、覆盖率与热流密度'));
 const evalPanel=document.createElement('section');evalPanel.className='panel evaluation-overview';const eTitle=document.createElement('div');eTitle.className='sectionbar';eTitle.innerHTML='<div><h2>当前设计是否满足目标</h2><p class="help">先看目标差距和缺项，再看分段结果。保存搭配仅用于条件对比。</p></div>';if(saveButton)eTitle.append(saveButton);evalPanel.append(eTitle);if(plan)evalPanel.append(plan);if(saved)evalPanel.append(saved);evaluation.append(evalPanel);if(resultHeading){resultHeading.querySelector('h2').textContent='分段核算与消耗账';evaluation.append(resultHeading);}if(results)evaluation.append(results);
 const audit=document.createElement('section');audit.className='panel';audit.innerHTML='<h2>评价系统完整性</h2><div id="system-audit">'+auditUI()+'</div>';basis.append(audit);const roadmap=document.createElement('section');roadmap.className='panel extension-panel';roadmap.innerHTML='<div><span class="audit-status missing">接入规划 · 尚未连接</span><h2>GPT、CAD 与 Fluent 可共用同一工作台</h2><p>当前网页只做本地条件计算。模型推理、几何转换与仿真求解需要后端服务，不能将参数图示当作已生成的 CAD 或 Fluent 结果。</p></div><a class="button-link" href="./platform.html">查看分阶段接入方案 ↗</a>';basis.append(roadmap);if(formula){formula.querySelector('h2').textContent='公式与计算口径';basis.append(collapsiblePanel(formula,'公式与计算口径','几何、连续流、动力学和热量平衡'));}if(evidencePanel){evidencePanel.querySelector('h2').textContent='文献参数与证据';basis.append(evidencePanel);}if(notice)basis.append(notice);
 app.replaceChildren(title,nav,design,evaluation,basis);if(dialog)app.append(dialog);document.querySelectorAll('#app details').forEach(d=>{if(openDisclosures.has(disclosureKey(d)))d.open=true;});switchWorkbench();}
function switchWorkbench(){document.querySelectorAll('[data-workbench-view]').forEach(x=>x.hidden=x.dataset.workbenchView!==uiView);document.querySelectorAll('[data-wb-view]').forEach(x=>{const active=x.dataset.wbView===uiView;x.setAttribute('aria-selected',String(active));x.tabIndex=active?0:-1;x.classList.toggle('active',active);});}

render();fetch('./bed-evidence.json').then(r=>{if(!r.ok)throw new Error('证据清单未载入');return r.json()}).then(data=>{evidence=data;renderEvidence()}).catch(()=>{$('#evidence').innerHTML='<p class="help">本页参考清单暂未载入，请打开完整证据库核对。</p>'});

fetch('./evidence/downloads/core-data.json').then(r=>{if(!r.ok)throw Error('设备目录未载入');return r.json()}).then(data=>{catalogue=data.equipment||[];types=Object.fromEntries(catalogue.filter(x=>!['TAP','CC','INGOT','VIMESRVAR','ROLLHT','SKIM','AR','POWDER','TDHEAT'].includes(x.equipment_id)).map(x=>[x.equipment_id,x.equipment_id+' · '+x.name]));state=migrateParallel(state);save();render();}).catch(()=>{status='设备数据包未加载，无法添加设备。';render();});

fetch('./system-audit.json').then(r=>{if(!r.ok)throw Error('audit unavailable');return r.json()}).then(data=>{systemAudit=data;const node=$('#system-audit');if(node)node.innerHTML=auditUI();}).catch(()=>{const node=$('#system-audit');if(node)node.innerHTML='<p class="help">审查清单暂未载入；仍需按模型边界核对，不能将未提供参数视为零。</p>';});

$('#app').addEventListener('keydown',e=>{const button=e.target.closest('[data-wb-view]');if(!button||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const keys=['design','evaluation','evidence'],i=keys.indexOf(uiView);uiView=e.key==='Home'?keys[0]:e.key==='End'?keys[2]:keys[(i+(e.key==='ArrowRight'?1:2))%3];switchWorkbench();document.querySelector('[data-wb-view="'+uiView+'"]').focus();});
